// SPDX-License-Identifier: GPL-3.0-only
//
// Codegen for a game's browser-safe routine registry.
//
// A browser has no node:fs and rejects file:// script loads from an http:// origin, so
// the registry cannot discover translated/ at runtime. This bakes it into a static
// import list that loads in Node and the browser alike.
//
//     node tools/gen-registry.mjs <game>
//
// Game-agnostic: it takes the id and reads games/<id>/translated/. Each game wires its
// own sync-check test against discover(), so a stale generated file fails loudly rather
// than dispatching a browser through the wrong table.

import { readdirSync, writeFileSync } from "node:fs";
import { fileURLToPath, pathToFileURL } from "node:url";
import { dirname, join } from "node:path";

const HERE = dirname(fileURLToPath(import.meta.url));

// A routine file: loc_ + exactly 4 hex digits + .js, which excludes .test.js and helpers.
const ROUTINE_FILE = /^loc_[0-9a-f]{4}\.js$/;
// An export owning a ROM address, both ends anchored, so a helper split
// loc_<parent>_<addr> does NOT claim one.
const ADDR_NAME = /^loc_([0-9a-f]{4})$/;

export function translatedDir(game) {
  return join(HERE, "..", "games", game, "translated");
}

/**
 * Every address-owning `loc_hhhh` export in translated/, in import order. Throws on a
 * collision so a leaked helper is found rather than silently shadowing a routine.
 */
export async function discover(game) {
  const dir = translatedDir(game);
  const files = readdirSync(dir).filter((f) => ROUTINE_FILE.test(f)).sort();
  const perFile = [];
  const owner = new Map();
  for (const file of files) {
    const mod = await import(pathToFileURL(join(dir, file)).href);
    const names = [];
    for (const [name, fn] of Object.entries(mod)) {
      if (typeof fn !== "function") continue;
      const m = ADDR_NAME.exec(name);
      if (!m) continue;
      const addr = parseInt(m[1], 16);
      if (owner.has(addr)) {
        throw new Error(
          `registry: 0x${addr.toString(16).padStart(4, "0")} claimed by both ` +
            `${owner.get(addr)} and ${name} (in ${file}) — name the helper ` +
            "loc_<parent>_<addr> so it does not claim an address.",
        );
      }
      owner.set(addr, name);
      names.push(name);
    }
    if (names.length) perFile.push({ file, names: names.sort() });
  }
  if (!owner.has(0x0000)) throw new Error(`registry: ${game} has no reset routine at 0x0000`);
  return perFile;
}

export function emit(game, perFile) {
  const out = [
    "// SPDX-License-Identifier: GPL-3.0-only",
    "// AUTO-GENERATED by tools/gen-registry.mjs — DO NOT EDIT BY HAND.",
    "// A browser-safe static routine registry: the address->function table baked as a",
    "// static import list, so the web player needs no node:fs and no file:// imports.",
    `//     node tools/gen-registry.mjs ${game}`,
    "",
  ];
  for (const { file, names } of perFile) {
    out.push(`import { ${names.join(", ")} } from "./${file}";`);
  }
  out.push("", "export const ROUTINE_ENTRIES = [");
  const rows = [];
  for (const { names } of perFile) {
    for (const name of names) rows.push([parseInt(ADDR_NAME.exec(name)[1], 16), name]);
  }
  rows.sort((a, b) => a[0] - b[0]);
  for (const [addr, name] of rows) {
    out.push(`  [0x${addr.toString(16).padStart(4, "0")}, ${name}],`);
  }
  out.push("];", "");
  return out.join("\n");
}

// Generate + write ONLY when invoked directly, so a sync-check test can import
// discover()/emit() without re-writing the file as a side effect -- and without the
// usage/exit(2) below firing during the importer's load.
if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const game = process.argv[2];
  if (!game) {
    console.error("usage: node tools/gen-registry.mjs <game>");
    process.exit(2);
  }
  const perFile = await discover(game);
  const outPath = join(translatedDir(game), "_registry.generated.js");
  writeFileSync(outPath, emit(game, perFile));
  console.log(`wrote ${outPath}`);
}
